class:
@startuml
' a small shop
interface Payable {
  +pay(amount : double) : boolean
}
abstract class Order {
  -id : int
  {static} +count : int
  +total() : double
}
class Customer<T> {
  +name : String {readOnly}
}
enum Status {
  OPEN
  PAID
}
class Invoice <<record>>
Order "1" *-- "0..*" Item : contains
Customer "1" --> "0..*" Order : places
Order ..|> Payable
Invoice --|> Order
Order ..> Status
@enduml

